def rotate(matrix):
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    rotated_matrix = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            rotated_matrix[j][n - i - 1] = matrix[i][j]

    return rotated_matrix

