import heapq

def solve(data):
    tasks = data['tasks']
    n = data['n']

    # Edge cases
    if not tasks:
        return 0
    if len(set(tasks)) == 1:
        return len(tasks)

    # Brute force approach
    def brute_force(n, tasks):
        time = 0
        for i in range(len(tasks)):
            if i % 2 == 0:
                time += 1
            else:
                time += 2
        return time

    # Check brute force on public examples
    assert brute_force(2, []) == 0
    assert brute_force(2, ['A', 'A', 'A', 'B', 'B', 'B']) == 8
    assert brute_force(0, ['A', 'B', 'C']) == 3
    assert brute_force(3, ['A', 'A']) == 5

    # Efficient solution using priority queue
    def min_time(n, tasks):
        if not tasks:
            return 0
        if len(set(tasks)) == 1:
            return len(tasks)

        tasks_count = {}
        for task in tasks:
            tasks_count[task] = tasks_count.get(task, 0) + 1

        max_heap = []
        for task, count in tasks_count.items():
            heapq.heappush(max_heap, (-count, task))

        total_time = 0
        while max_heap:
            count, task = heapq.heappop(max_heap)
            total_time += 1

            if count < -1:
                heapq.heappush(max_heap, (count + 1, task))

            if n > 0 and total_time % 2 == 0:
                total_time += n

        return total_time

    # Check efficient solution on public examples
    assert min_time(2, []) == 0
    assert min_time(2, ['A', 'A', 'A', 'B', 'B', 'B']) == 8
    assert min_time(0, ['A', 'B', 'C']) == 3
    assert min_time(3, ['A', 'A']) == 5

    return min_time(n, tasks)

