def solve(data: Dict[str, any]) -> int:
    tasks = data["tasks"]
    n = data["n"]

    if not tasks:
        return 0

    # Count occurrences of each task
    task_count = {}
    for task in tasks:
        if task in task_count:
            task_count[task] += 1
        else:
            task_count[task] = 1

    # Sort tasks by their occurrence count in descending order
    sorted_tasks = sorted(task_count.items(), key=lambda x: x[1], reverse=True)

    total_time = 0
    i = 0

    while i < len(sorted_tasks):
        # Add tasks with the highest frequency first
        total_time += sorted_tasks[i][1]

        # Check if there are enough idle slots to separate tasks
        if i + 1 < len(sorted_tasks) and sorted_tasks[i][1] == sorted_tasks[i+1][1]:
            total_time += n

        i += 1

    return total_time

